/*Table structure for table `template_info` */

DROP TABLE IF EXISTS `template_info`;

CREATE TABLE `template_info` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '公共素材标识',
  `fileName` varchar(50) DEFAULT NULL COMMENT '文件名',
  `userWorkId` varchar(100) DEFAULT NULL COMMENT '经销商标识',
  `typeName` varchar(50) DEFAULT NULL COMMENT '海报、视频、KV',
  `userId` varchar(100) DEFAULT NULL COMMENT '用户标识',
  `accountNumber` varchar(50) DEFAULT NULL COMMENT '账号',
  `coverUrl` varchar(255) DEFAULT NULL COMMENT '封面图',
  `templateJson` text COMMENT '模板信息JSON',
  `sourceUrl` varchar(255) DEFAULT NULL COMMENT '资源地址',
  `absolutelyUrl` varchar(255) DEFAULT NULL COMMENT '资源绝对地址',
  `isEdit` varchar(50) DEFAULT NULL COMMENT '是否编辑',
  `startTime` varchar(50) DEFAULT NULL COMMENT '期限开始时间',
  `endTime` varchar(50) DEFAULT NULL COMMENT '期限结束时间',
  `carModelName` varchar(50) DEFAULT NULL COMMENT '车型名称',
  `categoryName` varchar(50) DEFAULT NULL COMMENT '品类名称',
  `videoTime` varchar(50) DEFAULT NULL COMMENT '视频时长',
  `pictureHeight` varchar(50) DEFAULT NULL COMMENT '图片高度',
  `pictureWidth` varchar(50) DEFAULT NULL COMMENT '图片宽度',
  `width` varchar(50) DEFAULT NULL COMMENT '资源尺寸宽',
  `height` varchar(50) DEFAULT NULL COMMENT '资源尺寸高',
  `role` int(11) DEFAULT NULL COMMENT '1、经销商 2、区域 3、总部 4、超管',
  `materialType` int(11) DEFAULT NULL COMMENT '1、总部素材  2、区域素材    3、经销商素材',
  `uploadData` varchar(50) DEFAULT NULL COMMENT '上传时间',
  `createData` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=914 DEFAULT CHARSET=utf8;

