/*Table structure for table `user_info` */

DROP TABLE IF EXISTS `user_info`;

CREATE TABLE `user_info` (
  `id` varchar(50) NOT NULL COMMENT '标识',
  `accountNumber` varchar(50) DEFAULT NULL COMMENT '账号',
  `passWord` varchar(50) DEFAULT NULL COMMENT '密码',
  `userName` varchar(50) DEFAULT NULL COMMENT '姓名',
  `phone` varchar(50) DEFAULT NULL COMMENT '手机号',
  `email` varchar(50) DEFAULT NULL COMMENT '邮箱',
  `position` varchar(50) DEFAULT NULL COMMENT '职位',
  `region` varchar(50) DEFAULT NULL COMMENT '大区',
  `village` varchar(50) DEFAULT NULL COMMENT '小区',
  `province` varchar(50) DEFAULT NULL COMMENT '省份',
  `city` varchar(50) DEFAULT NULL COMMENT '城市',
  `distrName` varchar(50) DEFAULT NULL COMMENT '经销商',
  `disCode` varchar(50) DEFAULT NULL COMMENT '经销商代码',
  `role` int(11) DEFAULT NULL COMMENT '1、经销商 2、区域 3、总部',
  `status` int(11) DEFAULT NULL COMMENT '1、启用  2、禁用',
  `modify` int(11) DEFAULT NULL COMMENT '1、没修过  2、有修改',
  `updataStatus` int(11) DEFAULT '1' COMMENT '更新状态',
  `readStatus` int(11) DEFAULT NULL COMMENT '1、修改过',
  `updataData` varchar(50) NOT NULL COMMENT '更新时间',
  `creatData` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
