/*Table structure for table `user_share` */

DROP TABLE IF EXISTS `user_share`;

CREATE TABLE `user_share` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `type` varchar(11) DEFAULT NULL COMMENT '1、海报 2、视频',
  `userId` varchar(100) DEFAULT NULL COMMENT '用户标识',
  `createData` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `user_share` */

/*Table structure for table `user_template_info` */

DROP TABLE IF EXISTS `user_template_info`;

CREATE TABLE `user_template_info` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `templateId` int(11) DEFAULT NULL COMMENT '模板主表标识',
  `userId` varchar(50) DEFAULT NULL COMMENT '用户标识',
  `createData` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=329 DEFAULT CHARSET=utf8;

