/*Table structure for table `user_works_info` */

DROP TABLE IF EXISTS `user_works_info`;

CREATE TABLE `user_works_info` (
  `id` varchar(32) NOT NULL COMMENT '个人中心标识',
  `fileName` varchar(50) DEFAULT NULL COMMENT '文件名',
  `typeName` varchar(50) DEFAULT NULL COMMENT '视频、海报、KV、图片、音频',
  `userId` varchar(50) DEFAULT NULL COMMENT '用户标识',
  `accountNumber` varchar(50) DEFAULT NULL COMMENT '账号',
  `coverUrl` varchar(255) DEFAULT NULL COMMENT '封面图',
  `templateJson` text COMMENT '模板信息JSON',
  `sourceUrl` varchar(255) DEFAULT NULL COMMENT '资源地址',
  `absolutelyUrl` varchar(255) DEFAULT NULL COMMENT '资源绝对地址',
  `role` int(11) DEFAULT NULL COMMENT '1、经销商 2、区域 3、总部',
  `uploadData` varchar(50) DEFAULT NULL COMMENT '上传时间',
  `videoTime` varchar(50) DEFAULT NULL COMMENT '视频时长',
  `pictureHeight` varchar(50) DEFAULT NULL COMMENT '图片高度',
  `pictureWidth` varchar(50) DEFAULT NULL COMMENT '图片宽度',
  `width` varchar(50) DEFAULT NULL COMMENT '资源尺寸宽',
  `height` varchar(50) DEFAULT NULL COMMENT '资源尺寸高',
  `createData` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

